document.querySelectorAll("span[data-email-user][data-email-domain]").forEach(e=>{const n=`${e.dataset.emailUser}@${e.dataset.emailDomain}`,t=document.createElement("a");t.href=`mailto:${n}`,t.className=e.className,t.textContent=n,e.replaceWith(t)});const tooltipTriggerList=document.querySelectorAll('[data-bs-toggle="tooltip"]'),tooltipList=[...tooltipTriggerList].map(e=>new bootstrap.Tooltip(e))